sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float2 position;
uniform float radius;
uniform float brightness;
uniform float shine;
layout(color) uniform half4 color;
uniform float points;
uniform float alpha;
uniform float blend;
float3 blendWith(float m, float3 b, float3 s) {
    if (m < 0.5) return s;
    if (m < 1.5) return b * s;
    if (m < 2.5) return b + s - b * s;
    if (m < 3.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, b));
    if (m < 4.5) {
        float3 d = mix(sqrt(b), ((16.0 * b - 12.0) * b + 4.0) * b, step(b, float3(0.25)));
        return mix(b - (1.0 - 2.0 * s) * b * (1.0 - b), b + (2.0 * s - 1.0) * (d - b), step(0.5, s));
    }
    if (m < 5.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(0.5, s));
    if (m < 6.5) return min(b + s, 1.0);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return max(b, s);
    if (m < 9.5) return abs(b - s);
    if (m < 10.5) return min(b / max(1.0 - s, 0.0001), 1.0);
    return 1.0 - min((1.0 - b) / max(s, 0.0001), 1.0);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float2 p = coord - position * size;
    float r = length(p) / max(radius * 0.5 * min(size.x, size.y), 0.0001);
    float t = (dot(p, p) > 0.0 ? atan(p.y, p.x) : 0.0) + 1.5707963;
    float spike = pow(0.5 + 0.5 * cos(floor(points + 0.5) * t), 2.0);
    float rr = r / mix(0.12, 1.0, spike);
    float g = brightness / 3.0 * (1.8 * exp(-3.0 * rr) + 0.45 * exp(-2.0 * r / max(1.0 + shine, 0.05)));
    float3 glow = float3(color.rgb) * min(g, 1.0) + float3(max(g - 1.0, 0.0));
    float amount = clamp(alpha, 0.0, 1.0) * float(color.a);
    float3 base = float3(src.rgb) / float(src.a);
    float cover = clamp(g, 0.0, 1.0);
    float3 mixed = blend > 5.5 && blend < 6.5 ? min(base + glow, 1.0) : mix(base, clamp(blendWith(blend, base, clamp(glow, 0.0, 1.0)), 0.0, 1.0), cover);
    return half4(half3(mix(base, mixed, amount)) * src.a, src.a);
}
